<?php require '../common.php';startpage('Bus Bookings and Report');nav('<a href="index.php">Search</a><a href="admin.php">Admin</a>');$name=$_GET['passenger']??'';?><form><input name="passenger" placeholder="Passenger name (blank = all)" value="<?=e($name)?>"><button>View bookings/report</button></form><?php if($name){$s=$conn->prepare('SELECT bb.*,b.bus_name,b.origin,b.destination,b.travel_date FROM bus_bookings bb JOIN buses b ON b.id=bb.bus_id WHERE bb.passenger=?');$s->bind_param('s',$name);$s->execute();$rs=$s->get_result();}else{$rs=$conn->query('SELECT bb.*,b.bus_name,b.origin,b.destination,b.travel_date FROM bus_bookings bb JOIN buses b ON b.id=bb.bus_id');}?><table><tr><th>ID</th><th>Passenger</th><th>Bus</th><th>Route</th><th>Date</th><th>Seats</th><th>Status</th></tr><?php while($r=$rs->fetch_assoc()):?><tr><td><?=$r['id']?></td><td><?=e($r['passenger'])?></td><td><?=e($r['bus_name'])?></td><td><?=e($r['origin'])?> → <?=e($r['destination'])?></td><td><?=$r['travel_date']?></td><td><?=$r['seats']?></td><td><?=e($r['status'])?></td></tr><?php endwhile;?></table><?php endpage();?>